// Use Node.js or browser console for JavaScript coding
// Option 1: Run in browser console
console.log('Hello, DSA with JavaScript!');

// Option 2: Use Node.js
// Save this in app.js and run with `node app.js`
console.log('Setup complete.');

// JavaScript primitive data types
let name = 'Alice';      // String
let age = 25;            // Number
let isStudent = true;    // Boolean
let score = null;        // Null
let x;                   // Undefined
let id = Symbol();       // Symbol

// Object type
let user = {
  name: 'Bob',
  age: 30
};

// Conditional statements
let score = 85;
if (score >= 90) {
  console.log('A grade');
} else if (score >= 75) {
  console.log('B grade');
} else {
  console.log('C grade');
}

// Loops
for (let i = 0; i < 5; i++) {
  console.log('i =', i);
}

let i = 0;
while (i < 3) {
  console.log('while i =', i);
  i++;
}

// Function Declaration
function greet(name) {
  return `Hello, ${name}!`;
}

// Function Expression
const greetExpr = function(name) {
  return `Hi, ${name}!`;
};

// Arrow Function
const greetArrow = name => `Hey, ${name}!`;

console.log(greet('Alice'));
console.log(greetExpr('Bob'));
console.log(greetArrow('Charlie'));

// Simple Stack Implementation using Array
class Stack {
  constructor() {
    this.items = [];
  }
  push(item) {
    this.items.push(item);
  }
  pop() {
    return this.items.pop();
  }
  peek() {
    return this.items[this.items.length - 1];
  }
  isEmpty() {
    return this.items.length === 0;
  }
}

const stack = new Stack();
stack.push(10);
stack.push(20);
console.log(stack.pop()); // 20
